document.addEventListener("DOMContentLoaded",()=>{const e=document.getElementById("login-form");const r=document.getElementById("signup-form");if(e){e.addEventListener("submit",async r=>{r.preventDefault();clearAllErrors(e);const t=e.querySelector('button[type="submit"]');t.disabled=true;t.textContent="Logging in...";const a=document.getElementById("login-email").value.trim();const s=document.getElementById("login-password").value;let o=true;if(isEmpty(a)||!validateEmail(a)){showError("email-error","Please enter a valid email address.");o=false}if(isEmpty(s)){showError("password-error","Please enter your password.");o=false}if(!o){t.disabled=false;t.textContent="Login";return}try{const e=await WorkspaceApi("/login/","POST",{username:a,password:s},false);if(e.success&&e.data.token){saveAuthInfo(e.data.token,e.data.user);window.location.href="dashboard.html"}else{showGeneralError("login-general-error",e.error||"Login failed. Please check credentials.");t.disabled=false;t.textContent="Login"}}catch(e){console.error("Login error:",e);showGeneralError("login-general-error",e.message||"An unexpected error occurred. Please try again later.");t.disabled=false;t.textContent="Login"}})}if(r){r.addEventListener("submit",async e=>{e.preventDefault();clearAllErrors(r);const t=r.querySelector('button[type="submit"]');t.disabled=true;t.textContent="Signing up...";const a=document.getElementById("signup-fullname").value.trim();const s=document.getElementById("signup-email").value.trim();const o=document.getElementById("signup-password").value;const n=document.getElementById("signup-confirm-password").value;let l=true;if(isEmpty(a)){showError("fullname-error","Please enter your full name.");l=false}if(isEmpty(s)||!validateEmail(s)){showError("email-error","Please enter a valid email address.");l=false}if(isEmpty(o)||!validatePassword(o)){showError("password-error","Password must be at least 8 characters long.");l=false}if(o!==n){showError("confirm-password-error","Passwords do not match.");l=false}if(!l){t.disabled=false;t.textContent="Sign Up";return}const i={username:s,email:s,password:o,first_name:a.split(" ")[0]||"",last_name:a.split(" ").slice(1).join(" ")||""};try{const e=await WorkspaceApi("/register/","POST",i,false);if(e.success){try{const e=await WorkspaceApi("/login/","POST",{username:s,password:o},false);if(e.success&&e.data.token){saveAuthInfo(e.data.token,e.data.user);window.location.href="profile_setup.html"}else{console.warn("Auto-login failed after registration:",e.error);showGeneralError("signup-general-error",`Registration successful, but auto-login failed: ${e.error||"Please log in manually."}`);t.disabled=false;t.textContent="Sign Up"}}catch(e){console.error("Exception during auto-login attempt:",e);showGeneralError("signup-general-error",`Registration successful, but auto-login failed: ${e.message||"Please log in manually."}`);t.disabled=false;t.textContent="Sign Up"}}else{let r=e.error||"Registration failed. Please try again.";if(e.data&&typeof e.data==="object"){const t=Object.entries(e.data).map(([e,r])=>`${e}: ${Array.isArray(r)?r.join(", "):r}`).join("; ");if(t)r=t}showGeneralError("signup-general-error",r);t.disabled=false;t.textContent="Sign Up"}}catch(e){console.error("Signup error:",e);showGeneralError("signup-general-error",e.message||"An unexpected error occurred. Please try again later.");t.disabled=false;t.textContent="Sign Up"}})}});